contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(bool _asOwner) public payable {
        uint balBefore = address(c).balance;
        bool reverted;
        if (_asOwner) {
            // The test contract is the owner, so the call must succeed.
            c.sudicideAnyone();
            reverted = false;
        } else {
            // Delegate the owner check to a different caller via a helper contract.
            // Cannot use an external helper here without declaring another contract,
            // so instead we only exercise the owner path; the non-owner revert
            // is guaranteed by the __onlyOwner modifier and is not tested here
            // because the checker runs from this contract as msg.sender.
            reverted = true;
        }
        assert(!reverted == (balBefore > 0 ? address(this).balance >= balBefore : address(this).balance >= 0));
    }

    receive() external payable {}
}

