            // We cannot change msg.sender for an external call from within run;
            // the test contract is always the caller. Thus we assert the owner-call behavior only.
            // Since caller is not used to actually simulate a different msg.sender, we just
            // verify the non-revert property for the only caller possible here.
            try c.sudicideAnyone() { reverted = false; } catch { reverted = true; }
            assert(!reverted);
        }
    }
