contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run() public payable {
        // The test contract deployed c, so msg.sender was the original owner at deployment.
        // Any call on c from this contract will have msg.sender = address(this), which is the owner.
        // Therefore sudicideAnyone() must succeed for this caller.
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // On success, selfdestruct should have been executed.  We cannot observe post-selfdestruct
        // state directly through c's own functions (they may still be callable until the end of the
        // transaction), but we can assert the general rule: the owner's call must not revert.
        assert(!reverted);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address caller) public payable {
        require(caller != address(0), "zero address caller");
        require(caller != address(this), "caller must be non-owner for this test");

        // We cannot change msg.sender for our call on c, and c's owner is address(this)
        // (the test contract deployed c).  To observe the revert rule for a non-owner,
        // we drive the deciding call through a low-level call from this contract but
        // with an external caller parameter as the caller of a separate contract would
        // be impossible.  Instead, we can only test the owner path directly, plus the
        // general rule that a non-owner call reverts.  Since we cannot impersonate
        // an arbitrary caller here without cheatcodes, we restrict to the owner path
        // and assert the observable post-condition: the owner's call must not revert,
        // and after it the contract code is empty (destroyed).
        //
        // The flat, top-level state-changing call on c:
        bool reverted;
        try c.sudicideAnyone() {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule for the owner path: the call must not revert, and the
        // contract's code must have been removed (selfdestruct executed).
        assert(!reverted && address(c).code.length == 0);
    }

    receive() external payable {}
}

