        // still requires attempting the call. We attempt it as a top-level try statement.
        bool secondReverted;
        try c.sudicideAnyone() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        // General rule: for any input x, first owner call succeeds and a second call reverts.
        assert(secondReverted);
    }

    receive() external payable {}
}

