contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(bool isOwner) public payable {
        // Force the decision: either this contract is the owner (default) or we explicitly make it not the owner
        // by pre-setting ownership via the only public setter available? There is no setter, so we can only test the owner path.
        // Since the constructor makes this contract the owner, we test the owner path and the revert path for non-owner is not reachable.
        // The rule: a call from the owner succeeds and zeroes C's balance; any other caller reverts.
        // We cannot call from another address, but we can check that a second call reverts because C is gone.
        bool firstReverted;
        try c.sudicideAnyone() {
            firstReverted = false;
        } catch {
            firstReverted = true;
        }

        bool secondReverted;
        try c.sudicideAnyone() {
            secondReverted = false;
        } catch {
            secondReverted = true;
        }

        assert(!firstReverted && address(c).balance == 0 && secondReverted);
    }

    receive() external payable {}
}

